if (root == nullptr) {
    return;
}

if (item < root->value) {
    avlDelete(root->left, item);
} else if (item > root->value) {
    avlDelete(root->right, item);
} else {
    if (root->left == nullptr && root->right == nullptr) {
        delete root;
        root = nullptr;
    } else if (root->left == nullptr) {
        TreeNode<T>* temp = root;
        root = root->right;
        delete temp;
    } else if (root->right == nullptr) {
        TreeNode<T>* temp = root;
        root = root->left;
        delete temp;
    } else {
        TreeNode<T>* temp = bstFindMin(root->right);
        root->value = temp->value;
        avlDelete(root->right, temp->value);
    }
}

if (root != nullptr) {
    avlUpdateHeight(root);
    int balance = avlGetBalance(root);

    if (balance > 1) {
        if (avlGetBalance(root->left) >= 0) {
            avlRotateRight(root);
        } else {
            avlRotateLeft(root->left);
            avlRotateRight(root);
        }
    } else if (balance < -1) {
        if (avlGetBalance(root->right) <= 0) {
            avlRotateLeft(root);
        } else {
            avlRotateRight(root->right);
            avlRotateLeft(root);
        }
    }
}

